function getPath(obj,path){return path.split('.').reduce((a,k)=>a&&a[k]!==undefined?a[k]:undefined,obj)}
function setPath(obj,path,value){const parts=path.split('.');let cur=obj;parts.slice(0,-1).forEach(k=>{if(!cur[k]||typeof cur[k]!=='object'||Array.isArray(cur[k]))cur[k]={};cur=cur[k]});cur[parts.at(-1)]=value}
function firstVal(obj,paths){for(const p of paths.split('|')){const v=getPath(obj,p);if(v!==undefined&&v!==null&&String(v)!=='')return Array.isArray(v)?v.join('\n'):v}return ''}
