function renderNegociosOptions(){const tipo=el('negocioTipo')?.value||'outros',sel=el('negocioSelect');if(!sel)return;const atual=sel.value;sel.innerHTML=negocioOptions(tipo,atual);if(atual&&!Array.from(sel.options).some(o=>o.value===atual))sel.value='';const help=el('negocioHelp');if(help)help.textContent=sel.value==='__novo__'?'Crie o negócio no módulo correspondente e depois volte para selecionar aqui.':'Selecione um negócio já existente para liberar aprovação e promoção operacional.';renderPromotionPreview()}
function aplicarNegocioSelecionado(){const help=el('negocioHelp'),sel=el('negocioSelect');if(!sel||!help)return;if(sel.value==='__novo__')help.textContent='Crie o negócio no módulo correspondente e depois volte para selecionar aqui.';else if(sel.value)help.textContent='Negócio selecionado. A revisão pode ser aprovada quando os demais dados estiverem corretos.';else help.textContent='Selecione um negócio já existente para liberar aprovação e promoção operacional.';renderPromotionPreview()}
function validarNegocioOperacional(dados,target){if(target!=='compras')return;if(dados.negocio_novo_necessario)throw new Error('Crie o negócio primeiro e depois selecione o negócio existente nesta revisão.');if(!dados.operacao_id||!dados.operacao_codigo)throw new Error('Selecione um negócio existente antes de aprovar ou preparar promoção operacional.')}
function statusBadge(status){const cls=['realizado','executado','aprovado_confinex'].includes(status)?'b-green':(['rejeitado','cancelado','erro','erro_pos_gravacao'].includes(status)?'b-red':(['em_revisao','confirmado_telegram','em_execucao'].includes(status)?'b-blue':'b-amber'));return `<span class="badge ${cls}">${labelStatus(status||'sem status')}</span>`}
function labelStatus(s){return ({rascunho:'Rascunho',aguardando_confirmacao:'Aguardando confirmação',confirmado_telegram:'Confirmado no Telegram',em_revisao:'Em revisão',aprovado_confinex:'Aprovado no Confinex',em_execucao:'Em andamento',executado:'Concluído',realizado:'Realizado',erro_pos_gravacao:'Precisa conferir',rejeitado:'Rejeitado',cancelado:'Cancelado',erro:'Erro',expirado:'Expirado'})[s]||esc(s)}
function dadosItem(d,a){const payload=a?.payload||{};return d?.dados_extraidos||payload.dados_revisados||payload.dados_extraidos||payload}
function statusPrincipal(item){const d=item.draft||{},a=item.action||{};return a.acao_tipo==='promover_revisao_operacional'?a.status:(d.status||a.status)}
